Ben: No, Azadeh, if you interviewed people who buy organic produce, you’d see that they’re actually as selfish as everyone else, since they’re motivated only by worries about their own health.$batch07$ AND q.prompt=$batch07$Azadeh's and Ben's statements provide the most support for holding that they disagree about whether$batch07$ AND q.correct_choice=$batch07$D$batch07$) THEN RAISE EXCEPTION 'Question changed: PT120-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT120-S3-Q5$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S3-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT120-S3-Q5$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Azadeh's Position$batch07$, $batch07$More organic food production shows that consumers care more about the environment.$batch07$), (1, $batch07$Ben's Position$batch07$, $batch07$"No." Organic buyers are motivated only by worry about their own health.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Ben's "No" lands on Azadeh's first claim: that the organic increase shows environmental concern. Ben offers a different motive and never addresses the planet's future, or whether people ought to care.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether the rise in organic food shows more concern for the environment.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT120-S3-Q5$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Neither speaker talks about present eating habits keeping the planet healthy.$batch07$), ($batch07$B$batch07$, $batch07$Ben implies buyers *think* organic food is healthier. Whether it actually makes people healthier, neither says, and Azadeh never mentions health at all.$batch07$), ($batch07$C$batch07$, $batch07$Neither says how concerned people *ought* to be.$batch07$), ($batch07$D$batch07$, $batch07$Azadeh: the increase "indicates" greater environmental interest. Ben: the buyers care "only" about their own health.$batch07$), ($batch07$E$batch07$, $batch07$Neither speaker talks about persuading anyone.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT120-S3-Q5$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
